// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {FlashGovernanceArbiter} from "../src/FlashGovernanceArbiter.sol";

contract InvMutTest is Test {
    FlashGovernanceArbiter c;
    address stub;

    function setUp() public {
        __InvMutHandleStub s = new __InvMutHandleStub();
        stub = address(s);
        c = new FlashGovernanceArbiter(stub);
    }

    function testFuzz_property(uint256 amount, uint256 unlockTime, uint256 warpAhead) public {
        vm.assume(amount > 0 && amount < 2 ** 250);
        unlockTime = bound(unlockTime, 0, 10 ** 12);
        warpAhead = bound(warpAhead, 1, 10 ** 12);

        // configured == false, so onlySuccessfulProposal passes for anyone.
        c.configureFlashGovernance(stub, amount, unlockTime, false);

        // Deposit via the DAO (flashEnabled since msg.sender == DAO).
        vm.prank(stub);
        c.assertGovernanceApproved(stub, address(c), true);

        // Move past the unlock time.
        vm.warp(block.timestamp + unlockTime + warpAhead);

        // Withdraw as the depositor: must succeed when a nonzero amount is pending.
        vm.prank(stub);
        bool ok;
        try c.withdrawGovernanceAsset(address(c), stub) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}
contract __InvMutHandleStub {
    function factory() external view returns (address) { return address(this); }
    function createPair(address, address) external view returns (address) { return address(this); }
    function underlying() external view returns (address) { return address(this); }
    function WETH() external view returns (address) { return address(this); }
